description:
Write a function that swaps the keys and values of an object. If multiple keys have the same value, the last key wins.

Example:
- Input: { a: 1, b: 2, c: 3 } → Output: { 1: "a", 2: "b", 3: "c" }
- Input: { x: "hello", y: "world" } → Output: { hello: "x", world: "y" }

solutionCode:
function invertObject(obj) {
  const result = {};
  for (const [key, value] of Object.entries(obj)) {
    result[value] = key;
  }
  return result;
}
